import struct, itertools
def f(x):  # round to f32
    return struct.unpack('f', struct.pack('f', x))[0]
def bits(x):
    return struct.unpack('I', struct.pack('f', x))[0]

# candidate constants for yuv
c = {
 'y': [f(0.299), f(0.587), f(0.114)],
 'u': [f(-0.147), f(-0.289), f(0.436)],
 'v': [f(0.615), f(-0.515), f(-0.100)],
}

def dot(consts, rgb, order):
    # left-to-right sum of const[i]*rgb[i] in given order, f32 after each op
    terms = [f(consts[i]*rgb[i]) for i in order]
    s = terms[0]
    for t in terms[1:]:
        s = f(s+t)
    return s

