use super::{Cmyk, Hsl, Hsv, Rgb, Yuv};

pub struct ColorConverter;

fn clamp01(x: f32) -> f32 {
    if x < 0.0 {
        0.0
    } else if x > 1.0 {
        1.0
    } else {
        x
    }
}

// Shared hue computation for HSL/HSV (degrees, [0, 360)).
fn rgb_hue(rgb: Rgb, max: f32, d: f32) -> f32 {
    let mut h = if max == rgb.r {
        60.0 * ((rgb.g - rgb.b) / d % 6.0)
    } else if max == rgb.g {
        60.0 * ((rgb.b - rgb.r) / d + 2.0)
    } else {
        60.0 * ((rgb.r - rgb.g) / d + 4.0)
    };
    if h < 0.0 {
        h += 360.0;
    }
    h
}

fn hue2rgb(p: f32, q: f32, t: f32) -> f32 {
    let mut t = t;
    if t < 0.0 {
        t += 1.0;
    }
    if t > 1.0 {
        t -= 1.0;
    }
    if t < 1.0 / 6.0 {
        return p + (q - p) * 6.0 * t;
    }
    if t < 1.0 / 2.0 {
        return q;
    }
    if t < 2.0 / 3.0 {
        return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
    }
    p
}

impl ColorConverter {
    pub fn rgb_to_hsl(rgb: Rgb) -> Hsl {
        let max = rgb.r.max(rgb.g).max(rgb.b);
        let min = rgb.r.min(rgb.g).min(rgb.b);
        let l = (max + min) / 2.0;
        let mut h = 0.0f32;
        let mut s = 0.0f32;
        if max != min {
            let d = max - min;
            s = if l < 0.5 {
                d / (max + min)
            } else {
                d / (2.0 - max - min)
            };
            h = rgb_hue(rgb, max, d);
        }
        Hsl { h, s, l }
    }

    pub fn hsl_to_rgb(hsl: Hsl) -> Rgb {
        if hsl.s == 0.0 {
            return Rgb::new(hsl.l, hsl.l, hsl.l);
        }
        let q = if hsl.l < 0.5 {
            hsl.l * (1.0 + hsl.s)
        } else {
            hsl.l + hsl.s - hsl.l * hsl.s
        };
        let p = 2.0 * hsl.l - q;
        let hk = hsl.h / 360.0;
        let r = hue2rgb(p, q, hk + 1.0 / 3.0);
        let g = hue2rgb(p, q, hk);
        let b = hue2rgb(p, q, hk - 1.0 / 3.0);
        Rgb::new(r, g, b)
    }

    pub fn rgb_to_hsv(rgb: Rgb) -> Hsv {
        let max = rgb.r.max(rgb.g).max(rgb.b);
        let min = rgb.r.min(rgb.g).min(rgb.b);
        let d = max - min;
        let v = max;
        let s = if max == 0.0 { 0.0 } else { d / max };
        let h = if max == min { 0.0 } else { rgb_hue(rgb, max, d) };
        Hsv { h, s, v }
    }

    pub fn rgb_to_cmyk(rgb: Rgb) -> Cmyk {
        let max = rgb.r.max(rgb.g).max(rgb.b);
        let k = 1.0 - max;
        if k == 1.0 {
            return Cmyk {
                c: 0.0,
                m: 0.0,
                y: 0.0,
                k,
            };
        }
        let c = (1.0 - rgb.r - k) / (1.0 - k);
        let m = (1.0 - rgb.g - k) / (1.0 - k);
        let y = (1.0 - rgb.b - k) / (1.0 - k);
        Cmyk { c, m, y, k }
    }

    pub fn rgb_to_yuv(rgb: Rgb) -> Yuv {
        let y = 0.299 * rgb.r + 0.587 * rgb.g + 0.114 * rgb.b;
        let u = -0.147 * rgb.r + -0.289 * rgb.g + 0.436 * rgb.b;
        let v = 0.615 * rgb.r - 0.515 * rgb.g - 0.100 * rgb.b;
        Yuv { y, u, v }
    }

    pub fn adjust_brightness(rgb: Rgb, factor: f32) -> Rgb {
        Rgb::new(
            clamp01(rgb.r * factor),
            clamp01(rgb.g * factor),
            clamp01(rgb.b * factor),
        )
    }

    pub fn adjust_saturation(rgb: Rgb, factor: f32) -> Rgb {
        let mut hsl = Self::rgb_to_hsl(rgb);
        hsl.s = clamp01(hsl.s * factor);
        Self::hsl_to_rgb(hsl)
    }

    pub fn grayscale(rgb: Rgb) -> Rgb {
        let gray = 0.2126 * rgb.r + 0.7152 * rgb.g + 0.0722 * rgb.b;
        Rgb::new(gray, gray, gray)
    }

    pub fn invert(rgb: Rgb) -> Rgb {
        Rgb::new(1.0 - rgb.r, 1.0 - rgb.g, 1.0 - rgb.b)
    }

    pub fn color_distance(a: Rgb, b: Rgb) -> f32 {
        let dr = a.r - b.r;
        let dg = a.g - b.g;
        let db = a.b - b.b;
        (dr * dr + dg * dg + db * db).sqrt()
    }
}

