//! C++ `std::cout << float` compatible formatting (printf "%.6g" semantics).

/// Format an f32 exactly like C++ iostream's default float formatting,
/// which is equivalent to printf("%.6g", value).
pub fn format_g(x: f32) -> String {
    if x.is_nan() {
        return if x.is_sign_negative() { "-nan".to_string() } else { "nan".to_string() };
    }
    if x.is_infinite() {
        return if x < 0.0 { "-inf".to_string() } else { "inf".to_string() };
    }
    if x == 0.0 {
        return if x.is_sign_negative() { "-0".to_string() } else { "0".to_string() };
    }

    // Round to 6 significant digits through scientific notation.
    let sci = format!("{:.5e}", x); // e.g. "-3.57628e-7"
    let epos = sci.find('e').unwrap();
    let mant = &sci[..epos];
    let exp: i32 = sci[epos + 1..].parse().unwrap();
    let neg = mant.starts_with('-');
    let digits: String = mant.chars().filter(|c| c.is_ascii_digit()).collect();
    debug_assert_eq!(digits.len(), 6);

    if exp < -4 || exp >= 6 {
        // Scientific notation: strip trailing zeros of the mantissa,
        // exponent has a sign and at least two digits.
        let mut out = String::new();
        if neg {
            out.push('-');
        }
        out.push(digits.as_bytes()[0] as char);
        let frac = digits[1..].trim_end_matches('0');
        if !frac.is_empty() {
            out.push('.');
            out.push_str(frac);
        }
        let sign = if exp < 0 { '-' } else { '+' };
        out.push('e');
        out.push(sign);
        let ae = exp.unsigned_abs();
        if ae < 10 {
            out.push('0');
        }
        out.push_str(&ae.to_string());
        out
    } else if exp >= 0 {
        // Fixed notation, exponent in [0, 5].
        let split = exp as usize + 1;
        let mut out = String::new();
        if neg {
            out.push('-');
        }
        out.push_str(&digits[..split]);
        let frac = digits[split..].trim_end_matches('0');
        if !frac.is_empty() {
            out.push('.');
            out.push_str(frac);
        }
        out
    } else {
        // Fixed notation, exponent in [-4, -1]: 0.00ddd
        let mut out = String::new();
        if neg {
            out.push('-');
        }
        out.push_str("0.");
        for _ in 0..(-exp - 1) {
            out.push('0');
        }
        let frac = digits.trim_end_matches('0');
        out.push_str(frac);
        out
    }
}

