mod cfmt;
mod color;

use cfmt::format_g;
use color::{ColorConverter, Rgb};

/// Mimic C++ `std::stof`: skip leading whitespace, parse the longest valid
/// float prefix, ignore trailing garbage.
fn stof(s: &str) -> f32 {
    let trimmed = s.trim_start();
    let bytes = trimmed.as_bytes();
    let mut end = 0;

    let mut i = 0;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        i += 1;
    }
    // inf / nan (case-insensitive), like strtof.
    let lower = trimmed[i..].to_ascii_lowercase();
    if lower.starts_with("infinity") {
        end = i + 8;
    } else if lower.starts_with("inf") || lower.starts_with("nan") {
        end = i + 3;
    } else {
        let mut saw_digit = false;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
            saw_digit = true;
        }
        if i < bytes.len() && bytes[i] == b'.' {
            i += 1;
            while i < bytes.len() && bytes[i].is_ascii_digit() {
                i += 1;
                saw_digit = true;
            }
        }
        if saw_digit {
            end = i;
            // optional exponent
            if i < bytes.len() && (bytes[i] == b'e' || bytes[i] == b'E') {
                let mut j = i + 1;
                if j < bytes.len() && (bytes[j] == b'+' || bytes[j] == b'-') {
                    j += 1;
                }
                let exp_start = j;
                while j < bytes.len() && bytes[j].is_ascii_digit() {
                    j += 1;
                }
                if j > exp_start {
                    end = j;
                }
            }
        } else {
            // std::stof throws std::invalid_argument; abort like the C++ binary.
            std::process::abort();
        }
    }

    trimmed[..end].parse::<f32>().unwrap_or_else(|_| std::process::abort())
}

fn push_val(out: &mut String, v: f32) {
    out.push_str(&format_g(v));
    out.push(' ');
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut colors: Vec<Rgb> = Vec::new();
    colors.push(Rgb::new(0.1, 0.2, 0.3));
    colors.push(Rgb::new(0.4, 0.5, 0.6));
    colors.push(Rgb::new(0.7, 0.2, 0.1));
    colors.push(Rgb::new(0.3, 0.8, 0.4));
    colors.push(Rgb::new(0.9, 0.1, 0.8));

    let argc = args.len();
    let mut i = 1;
    while i + 2 < argc {
        let r = stof(&args[i]);
        let g = stof(&args[i + 1]);
        let b = stof(&args[i + 2]);
        colors.push(Rgb::new(r, g, b));
        i += 3;
    }

    let mut out = String::new();
    for i in 0..colors.len() {
        let rgb = colors[i];

        let hsl = ColorConverter::rgb_to_hsl(rgb);
        let hsv = ColorConverter::rgb_to_hsv(rgb);
        let cmyk = ColorConverter::rgb_to_cmyk(rgb);
        let yuv = ColorConverter::rgb_to_yuv(rgb);

        let bright = ColorConverter::adjust_brightness(rgb, 1.2);
        let dark = ColorConverter::adjust_brightness(rgb, 0.8);

        let saturated = ColorConverter::adjust_saturation(rgb, 1.5);

        let gray = ColorConverter::grayscale(rgb);

        let inverted = ColorConverter::invert(rgb);

        out.push_str(&format!("Color {}: ", i));
        push_val(&mut out, rgb.r);
        push_val(&mut out, rgb.g);
        push_val(&mut out, rgb.b);
        push_val(&mut out, hsl.h);
        push_val(&mut out, hsl.s);
        push_val(&mut out, hsl.l);
        push_val(&mut out, hsv.h);
        push_val(&mut out, hsv.s);
        push_val(&mut out, hsv.v);
        push_val(&mut out, cmyk.c);
        push_val(&mut out, cmyk.m);
        push_val(&mut out, cmyk.y);
        push_val(&mut out, cmyk.k);
        push_val(&mut out, yuv.y);
        push_val(&mut out, yuv.u);
        push_val(&mut out, yuv.v);
        push_val(&mut out, bright.r);
        push_val(&mut out, bright.g);
        push_val(&mut out, bright.b);
        push_val(&mut out, dark.r);
        push_val(&mut out, dark.g);
        push_val(&mut out, dark.b);
        push_val(&mut out, saturated.r);
        push_val(&mut out, saturated.g);
        push_val(&mut out, saturated.b);
        push_val(&mut out, gray.r);
        push_val(&mut out, gray.g);
        push_val(&mut out, gray.b);
        push_val(&mut out, inverted.r);
        push_val(&mut out, inverted.g);
        push_val(&mut out, inverted.b);

        if i == colors.len() - 1 && colors.len() > 1 {
            let dist = ColorConverter::color_distance(rgb, colors[0]);
            push_val(&mut out, dist);
        }

        out.push('\n');
    }

    print!("{}", out);
}

