cat > /tmp/probe/v.rs <<'EOF'
fn h(rgb:[f32;3], max:f32, d:f32) -> f32 {
    let mut h = if max == rgb[0] {
        60.0 * ((rgb[1] - rgb[2]) / d % 6.0)
    } else if max == rgb[1] {
        60.0 * ((rgb[2] - rgb[0]) / d + 2.0)
    } else {
        60.0 * ((rgb[0] - rgb[1]) / d + 4.0)
    };
    if h < 0.0 { h += 360.0; }
    h
}
fn main() {
    // case3: rgb = (0.55553, 0.1, 1), expect r prints 0.55553 (cpp) vs 0.555531 (mine)
    let rgb = [0.55553f32, 0.1, 1.0];
    let max = 1.0f32; let min = 0.1f32;
    let l = (max+min)/2.0;
    let d = max - min;
    let s = (d / (2.0 - max - min) * 1.5).min(1.0f32);
    let hh = h(rgb, max, d);
    let q = if l < 0.5 { l*(1.0+s) } else { l+s-l*s };
    let p = 2.0*l - q;
    let hk = hh / 360.0;
    println!("l={:?} s={:?} h={:?} hk={:?} p={:?} q={:?}", l, s, hh, hk, p, q);
    // r channel: t = hk + 1/3, >1 => -1
    let t = hk + 1.0/3.0 - 1.0;
    println!("t={:?}", t);
    let v1 = p + ((q-p)*6.0)*t;
    let v2 = p + (q-p)*(6.0*t);
    let v3 = p + ((q-p)*t)*6.0;
    let v4 = p + 6.0*t*(q-p);      // (6*t)*(q-p)
    let v5 = p + t*6.0*(q-p);      // (t*6)*(q-p)
    println!("v1={:?} v2={:?} v3={:?} v4={:?} v5={:?}", v1, v2, v3, v4, v5);
    println!("prints: {:.6} {:.6} {:.6} {:.6} {:.6}", v1, v2, v3, v4, v5);
    // also double-precision t variants
    let td = ((hk as f64 + 1.0/3.0) - 1.0) as f32;
    println!("td={:?}", td);
    let w1 = p + ((q-p)*6.0)*td;
    let w2 = p + (q-p)*(6.0*td);
    println!("w1={:?} w2={:?} prints {:.6} {:.6}", w1, w2, w1, w2);
}
