fn h2r_d(p: f32, q: f32, t: f32) -> f32 {
    let mut t = t;
    if t < 0.0 { t += 1.0; }
    if t > 1.0 { t -= 1.0; }
    let (pd, qd, td) = (p as f64, q as f64, t as f64);
    if td < 1.0/6.0 { return (pd + (qd - pd) * 6.0 * td) as f32; }
    if td < 1.0/2.0 { return q; }
    if td < 2.0/3.0 { return (pd + (qd - pd) * (2.0/3.0 - td) * 6.0) as f32; }
    p
